"use client";

import Link from "next/link";
import {useEffect,useState} from "react";
import {getSupabaseBrowserClient} from "@/lib/supabase-browser";

type Candidate={id:string;topic:string;content:string;status:string;created_at:string;reviewed_at?:string|null};
type Knowledge={id:string;topic:string;content:string;version:number;published:boolean;updated_at:string};

export default function AiLearningAdmin(){
  const [candidates,setCandidates]=useState<Candidate[]>([]);
  const [knowledge,setKnowledge]=useState<Knowledge[]>([]);
  const [message,setMessage]=useState("");

  async function headers():Promise<Record<string,string>>{
    const supabase=getSupabaseBrowserClient();
    const {data:{session}}=await supabase.auth.getSession();
    return session?.access_token?{Authorization:"Bearer "+session.access_token}:{};
  }
  async function load(){
    const response=await fetch("/api/admin/ai-learning",{headers:await headers(),cache:"no-store"});
    const data=await response.json();
    if(!response.ok){setMessage(data?.error||"Нет доступа.");return;}
    setCandidates(data.candidates||[]);setKnowledge(data.knowledge||[]);
  }
  useEffect(()=>{void load()},[]);

  async function act(action:"approve"|"reject"|"unpublish",id:string){
    if(action==="approve"&&!window.confirm("Опубликовать этот материал в проверенной базе знаний помощника?"))return;
    const response=await fetch("/api/admin/ai-learning",{method:"POST",headers:{...(await headers()),"Content-Type":"application/json"},body:JSON.stringify({action,id})});
    const data=await response.json();
    setMessage(response.ok?"Изменение сохранено.":data?.error||"Ошибка.");
    if(response.ok)await load();
  }

  return <main className="legal-page"><div className="legal-shell">
    <Link className="brand" href="/platform">KIVRONIX<span>.</span></Link>
    <div className="eyebrow">ADMIN · БЕЗОПАСНОЕ ОБУЧЕНИЕ ИИ</div>
    <h1>Очередь улучшений</h1>
    <p>Отзывы пользователей сначала попадают на проверку. Помощник использует материал только после явного одобрения администратора.</p>
    {message?<div className="auth-msg" role="status">{message}</div>:null}
    <section className="legal-card"><h2>На проверке</h2>
      <div className="business-stack">{candidates.filter(item=>item.status==="pending").map(item=><article className="ai-learning-item" key={item.id}>
        <div><b>{item.topic}</b><small>{new Date(item.created_at).toLocaleString("ru-RU")}</small></div>
        <pre>{item.content}</pre>
        <div className="lesson-actions"><button className="btn btn-lime" onClick={()=>void act("approve",item.id)}>Одобрить и опубликовать</button><button className="btn btn-ghost" onClick={()=>void act("reject",item.id)}>Отклонить</button></div>
      </article>)}</div>
      {!candidates.some(item=>item.status==="pending")?<p className="muted">Очередь пуста.</p>:null}
    </section>
    <section className="legal-card"><h2>Опубликованная база</h2>
      <div className="business-stack">{knowledge.map(item=><article className="ai-learning-item" key={item.id}><div><b>{item.topic}</b><small>Версия {item.version} · {item.published?"используется":"выключена"}</small></div><pre>{item.content}</pre>{item.published?<button className="btn btn-ghost" onClick={()=>void act("unpublish",item.id)}>Снять с публикации</button>:null}</article>)}</div>
      {!knowledge.length?<p className="muted">Одобренных материалов пока нет.</p>:null}
    </section>
  </div></main>;
}

"use client";

import Link from "next/link";
import {useEffect,useState} from "react";
import {getSupabaseBrowserClient} from "@/lib/supabase-browser";

type Row={
  id:string;legal_name:string;inn?:string|null;registration_number?:string|null;
  website_url?:string|null;social_url?:string|null;reported_audience?:number|null;
  requested_level:string;status:string;created_at:string;review_note?:string|null;
  businesses?:{name?:string}|null;documents?:{path:string;url:string}[];
};

export default function BusinessVerificationAdmin(){
  const [rows,setRows]=useState<Row[]>([]);
  const [message,setMessage]=useState("Загружаем…");

  async function headers():Promise<Record<string,string>>{
    const supabase=getSupabaseBrowserClient();
    const {data:{session}}=await supabase.auth.getSession();
    return session?.access_token?{Authorization:"Bearer "+session.access_token}:{};
  }

  async function load(){
    const h=await headers();
    const r=await fetch("/api/admin/business-verification",{headers:h,cache:"no-store"});
    const data=await r.json();
    if(!r.ok){setMessage(data?.error||"Нет доступа.");return;}
    setRows(data.requests||[]);
    setMessage(data.requests?.length?"":"Новых заявок нет.");
  }

  useEffect(()=>{void load()},[]);

  async function act(id:string,action:"approve"|"needs_info"|"reject",level?:string){
    const note=window.prompt(action==="approve"?"Комментарий (можно оставить пустым)":"Напиши понятную причину для бизнеса:")||"";
    const h=await headers();
    const r=await fetch("/api/admin/business-verification",{
      method:"POST",
      headers:{...h,"Content-Type":"application/json"},
      body:JSON.stringify({requestId:id,action,level,note})
    });
    const data=await r.json();
    setMessage(r.ok?"Готово.":data?.error||"Ошибка.");
    if(r.ok)await load();
  }

  return <main className="legal-page"><div className="legal-shell">
    <Link href="/platform" className="brand">KIVRONIX<span>.</span></Link>
    <div className="eyebrow">ADMIN · BUSINESS VERIFICATION</div>
    <h1>Проверка компаний</h1>
    <p>Документы закрыты от обычных пользователей. Ссылки ниже временные и нужны только для ручной проверки.</p>
    {message&&<div className="auth-msg">{message}</div>}
    <div className="business-stack">
      {rows.map(row=><section className="legal-card" key={row.id}>
        <div className="verification-head"><div><div className="eyebrow">{row.requested_level==="popular_brand"?"ЗАПРОС: ИЗВЕСТНЫЙ БРЕНД":"ЗАПРОС: ПРОВЕРЕННАЯ КОМПАНИЯ"}</div><h2>{row.legal_name}</h2></div><span className="verification-badge pending">{row.status}</span></div>
        <p><b>ИНН:</b> {row.inn||"—"} · <b>ОГРН/ОГРНИП:</b> {row.registration_number||"—"}</p>
        {row.website_url&&<p><a href={row.website_url} target="_blank" rel="noreferrer"><u>Открыть сайт ↗</u></a></p>}
        {row.social_url&&<p><a href={row.social_url} target="_blank" rel="noreferrer"><u>Открыть публичную страницу ↗</u></a>{row.reported_audience!=null?" · заявлено "+row.reported_audience.toLocaleString("ru-RU")+" подписчиков":""}</p>}
        <div className="source-assets"><b>Документы:</b>{(row.documents||[]).map((d,i)=><a key={d.path} href={d.url} target="_blank" rel="noreferrer">Документ {i+1} ↗</a>)}</div>
        <div className="lesson-actions">
          <button className="btn btn-dark" onClick={()=>act(row.id,"approve","verified_company")}>✓ Проверенная компания</button>
          <button className="btn btn-lime" onClick={()=>act(row.id,"approve","popular_brand")}>★ Известный бренд</button>
          <button className="btn btn-ghost" onClick={()=>act(row.id,"needs_info")}>Нужно уточнение</button>
          <button className="btn btn-ghost" onClick={()=>act(row.id,"reject")}>Отклонить</button>
        </div>
      </section>)}
    </div>
  </div></main>
}

"use client";

import Link from "next/link";
import {useEffect,useState} from "react";
import {getSupabaseBrowserClient} from "@/lib/supabase-browser";

type Application={
  id:string;display_name:string;email:string;social_url?:string|null;portfolio_url?:string|null;
  preferred_format?:string|null;desired_rate?:string|null;note?:string|null;status:string;created_at:string;
};
type Interest={
  id:string;email:string;social_url?:string|null;message?:string|null;status:string;created_at:string;
  creator_briefs?:{title?:string;slug?:string}|null;
};

export default function CreatorsAdmin(){
  const [applications,setApplications]=useState<Application[]>([]);
  const [interest,setInterest]=useState<Interest[]>([]);
  const [message,setMessage]=useState("Загружаем…");

  async function headers():Promise<Record<string,string>>{
    const supabase=getSupabaseBrowserClient();
    const {data:{session}}=await supabase.auth.getSession();
    return session?.access_token?{Authorization:"Bearer "+session.access_token}:{};
  }

  async function load(){
    const h=await headers();
    const r=await fetch("/api/admin/creators",{headers:h,cache:"no-store"});
    const data=await r.json();
    if(!r.ok){setMessage(data?.error||"Нет доступа.");return;}
    setApplications(data.applications||[]);
    setInterest(data.interest||[]);
    setMessage("");
  }

  useEffect(()=>{void load()},[]);

  async function setStatus(kind:"application"|"interest",id:string,status:string){
    const h=await headers();
    const r=await fetch("/api/admin/creators",{
      method:"POST",
      headers:{...h,"Content-Type":"application/json"},
      body:JSON.stringify({kind,id,status})
    });
    const data=await r.json();
    setMessage(r.ok?"Готово.":data?.error||"Ошибка.");
    if(r.ok)await load();
  }

  return <main className="legal-page"><div className="legal-shell">
    <Link href="/platform" className="brand">KIVRONIX<span>.</span></Link>
    <div className="eyebrow">АДМИН · МОНТАЖЁРЫ KIVRONIX</div>
    <h1>Команда монтажёров</h1>
    <p>Здесь заявки в постоянную команду и отклики на официальные задания KIVRONIX.</p>
    {message&&<div className="auth-msg">{message}</div>}

    <h2>Заявки в постоянную команду</h2>
    <div className="business-stack">
      {applications.length===0&&<div className="auth-msg">Заявок пока нет.</div>}
      {applications.map(a=><section className="legal-card" key={a.id}>
        <div className="verification-head"><div><div className="eyebrow">КОМАНДА МОНТАЖЁРОВ</div><h2>{a.display_name}</h2></div><span className="verification-badge">{a.status}</span></div>
        <p><b>Электронная почта:</b> {a.email}</p>
        {a.social_url&&<p><a href={a.social_url} target="_blank" rel="noreferrer"><u>Соцсеть ↗</u></a></p>}
        {a.portfolio_url&&<p><a href={a.portfolio_url} target="_blank" rel="noreferrer"><u>Работы автора ↗</u></a></p>}
        <p><b>Что снимает:</b> {a.preferred_format||"—"}<br/><b>Ожидание по оплате:</b> {a.desired_rate||"—"}</p>
        {a.note&&<p>{a.note}</p>}
        <div className="lesson-actions"><button className="btn btn-dark" onClick={()=>setStatus("application",a.id,"approved")}>Принять в команду</button><button className="btn btn-ghost" onClick={()=>setStatus("application",a.id,"paused")}>Отложить</button><button className="btn btn-ghost" onClick={()=>setStatus("application",a.id,"rejected")}>Пропустить</button></div>
      </section>)}
    </div>

    <h2 style={{marginTop:36}}>Отклики на задания</h2>
    <div className="business-stack">
      {interest.length===0&&<div className="auth-msg">Откликов пока нет.</div>}
      {interest.map(i=><section className="legal-card" key={i.id}>
        <div className="verification-head"><div><div className="eyebrow">ОТКЛИК НА ЗАДАНИЕ</div><h2>{i.creator_briefs?.title||"Задание KIVRONIX"}</h2></div><span className="verification-badge">{i.status}</span></div>
        <p><b>Электронная почта:</b> {i.email}</p>
        {i.social_url&&<p><a href={i.social_url} target="_blank" rel="noreferrer"><u>Профиль ↗</u></a></p>}
        {i.message&&<p>{i.message}</p>}
        <div className="lesson-actions"><button className="btn btn-dark" onClick={()=>setStatus("interest",i.id,"contacted")}>Связь начата</button><button className="btn btn-lime" onClick={()=>setStatus("interest",i.id,"accepted")}>Согласовали работу</button><button className="btn btn-ghost" onClick={()=>setStatus("interest",i.id,"declined")}>Пропустить</button></div>
      </section>)}
    </div>
  </div></main>
}

