  }
  return GET(req);
}

import {NextRequest,NextResponse} from "next/server";
import {getSupabaseServiceClient,getUserFromAccessToken} from "@/lib/server-supabase";
import type {FuturePlanId,PlanAudience} from "@/lib/plans";

const choices:Record<PlanAudience,FuturePlanId>={editor:"creator_plus",business:"studio_plus"};

function bearer(req:NextRequest){
  const value=req.headers.get("authorization");
  return value?.startsWith("Bearer ")?value.slice(7):null;
}

export async function POST(req:NextRequest){
  const user=await getUserFromAccessToken(bearer(req));
  const service=getSupabaseServiceClient();
  if(!user||!service)return NextResponse.json({error:"Нужен вход в KIVRONIX."},{status:401});

  const body=await req.json().catch(()=>({}));
  const audience=String(body?.audience||"") as PlanAudience;
  const plan=String(body?.plan||"") as FuturePlanId;
  if(!(audience in choices)||choices[audience]!==plan){
    return NextResponse.json({error:"Такой тариф пока отсутствует."},{status:400});
  }

  const {data:profile}=await service.from("profiles").select("role").eq("id",user.id).maybeSingle();
  const expectedAudience=profile?.role==="business"?"business":"editor";
  if(audience!==expectedAudience){
    return NextResponse.json({error:"Тариф должен соответствовать типу аккаунта."},{status:409});
  }

  const {error}=await service.from("future_plan_interest").upsert({
    user_id:user.id,
    audience,
    wanted_plan:plan,
    updated_at:new Date().toISOString()
  },{onConflict:"user_id"});
  if(error)return NextResponse.json({error:"Интерес пока не сохранился."},{status:500});
  return NextResponse.json({ok:true,audience,plan,paymentsEnabled:false});
}

import {NextRequest,NextResponse} from "next/server";
import {getSupabaseServiceClient,getUserFromAccessToken} from "@/lib/server-supabase";

function bearer(req:NextRequest){
  const value=req.headers.get("authorization");
  return value?.startsWith("Bearer ")?value.slice(7):null;
}

async function access(req:NextRequest){
  const user=await getUserFromAccessToken(bearer(req));
  const service=getSupabaseServiceClient();
  return user&&service?{user,service}:null;
}

export async function GET(req:NextRequest){
  const a=await access(req);
  if(!a)return NextResponse.json({error:"Нужен вход."},{status:401});
  const {data,error}=await a.service.from("practice_sessions")
    .select("scenario,messages,result,updated_at")
    .eq("user_id",a.user.id)
    .maybeSingle();
  if(error)return NextResponse.json({error:"Ошибка загрузки тренировки."},{status:503});
  return NextResponse.json({session:data||null});
}

export async function POST(req:NextRequest){
  const a=await access(req);
  if(!a)return NextResponse.json({error:"Нужен вход."},{status:401});
  const body=await req.json().catch(()=>({}));
  const scenario=String(body?.scenario||"").trim().slice(0,2000);
  const messages=Array.isArray(body?.messages)?body.messages.slice(-50).map((item:any)=>({
    from:item?.from==="client"?"client":"user",
    text:String(item?.text||"").trim().slice(0,2000)
  })).filter((item:any)=>item.text):[];
  const rawResult=body?.result&&typeof body.result==="object"?body.result:null;
  const result=rawResult?{
    client_reply:String(rawResult.client_reply||"").slice(0,2000),
    score:Math.max(0,Math.min(100,Number(rawResult.score)||0)),
    feedback:String(rawResult.feedback||"").slice(0,3000),
    better_answer:String(rawResult.better_answer||"").slice(0,3000)
  }:null;
  const {error}=await a.service.from("practice_sessions").upsert({
    user_id:a.user.id,scenario,messages,result,updated_at:new Date().toISOString()
  },{onConflict:"user_id"});
  if(error)return NextResponse.json({error:"Ошибка сохранения тренировки."},{status:503});
  return NextResponse.json({ok:true});
}

