.private-chat-safety{margin:14px 16px 0;padding:12px 14px;border:1px solid #d4e592;border-radius:14px;background:#f4f9dc;display:grid;gap:4px}.private-chat-safety b{font-size:12px}.private-chat-safety span{font-size:11px;line-height:1.45;color:#5f6752}.private-chat-messages{flex:1;min-height:350px;max-height:520px;overflow-y:auto;padding:18px;display:flex;flex-direction:column;gap:9px}.private-chat-messages article{align-self:flex-start;max-width:min(76%,560px);padding:11px 13px;border-radius:15px 15px 15px 4px;background:#eee;display:grid;gap:5px}.private-chat-messages article.mine{align-self:flex-end;border-radius:15px 15px 4px;background:var(--dark);color:white}.private-chat-messages article p{margin:0;line-height:1.45;white-space:pre-wrap;overflow-wrap:anywhere}.private-chat-messages article time{font-size:9px;color:#8a8c84}.private-chat-messages article.mine time{color:#aeb0a8;text-align:right}
.private-chat-form{display:grid;grid-template-columns:minmax(0,1fr) auto;gap:9px;padding:14px;border-top:1px solid var(--line)}.private-chat-form textarea{min-height:48px;max-height:130px;resize:vertical;border:1px solid var(--line);border-radius:13px;padding:12px}.private-chat-zero,.private-chat-start,.private-chat-empty{margin:auto;text-align:center;display:grid;justify-items:center;gap:7px;padding:24px;color:var(--muted)}.private-chat-zero>span,.private-chat-start>span,.private-chat-lock{font-size:28px}.private-chat-zero b,.private-chat-start b,.private-chat-empty h3{color:var(--ink);margin:0}.private-chat-zero p,.private-chat-start p{max-width:330px;margin:0;font-size:12px;line-height:1.5}.private-chat-zero.large{height:100%}.private-chat-empty{min-height:360px}
@media(max-width:760px){.private-chat-shell{grid-template-columns:1fr;min-height:0}.private-chat-list{border-right:0;border-bottom:1px solid var(--line);max-height:230px;overflow-y:auto}.private-chat-thread>header{align-items:flex-start}.private-chat-badge{display:none}.private-chat-messages{min-height:330px}.private-chat-form{grid-template-columns:1fr}.private-chat-form .btn{width:100%}.private-chat-messages article{max-width:88%}}
.profile-friend-row>div{flex:0 1 auto}.profile-friend-row>div:first-of-type{flex:1}
.practice-storage{display:inline-flex;margin:-6px 0 8px;color:var(--muted);font-size:10px;font-weight:800}
.academy-start-card{display:flex;justify-content:space-between;align-items:center;gap:24px;background:var(--dark);color:white;border-radius:22px;padding:24px;margin:0 0 18px}.academy-start-card h2{font-size:28px;margin:7px 0}.academy-start-card p{color:#c8c9c3;line-height:1.5;margin:0;max-width:720px}.academy-start-card .eyebrow{color:#bfc0b8}.academy-start-card .btn{flex:0 0 auto}.ai-learning-note{display:grid;gap:5px;background:#eef7c9;border:1px solid #cfdf88;border-radius:16px;padding:16px;margin-bottom:14px}.ai-learning-note span{font-size:13px;line-height:1.5;color:#586044}@media(max-width:700px){.academy-start-card{align-items:stretch;flex-direction:column}.academy-start-card .btn{width:100%}}
.insights-hub{display:grid;gap:16px}.insights-topic{display:flex;align-items:center;justify-content:space-between;gap:24px;background:linear-gradient(130deg,#211f96,#5c4bd5);color:white;border-radius:24px;padding:28px}.insights-topic h2{font-size:clamp(28px,4vw,46px);letter-spacing:-2px;line-height:1;margin:9px 0 12px}.insights-topic p{color:#dddafa;line-height:1.5;margin:0}.insights-topic .eyebrow{color:#d7d4ff}.insights-grid{display:grid;grid-template-columns:repeat(3,1fr);gap:12px}.insight-card{background:white;border:1px solid var(--line);border-radius:20px;padding:20px;display:flex;flex-direction:column;align-items:flex-start}.insight-card>span{font-size:10px;font-weight:1000;text-transform:uppercase;background:var(--soft);border-radius:999px;padding:6px 8px}.insight-card h3{font-size:23px;line-height:1.08;margin:18px 0 9px}.insight-card p,.insight-body{color:var(--muted);line-height:1.55}.insight-body{font-size:14px;border-top:1px solid var(--line);padding-top:12px;margin-top:4px}.insight-toggle{border:0;background:transparent;padding:12px 0 0;font-weight:900;cursor:pointer;margin-top:auto}@media(max-width:900px){.insights-grid{grid-template-columns:1fr 1fr}}@media(max-width:650px){.insights-topic{align-items:stretch;flex-direction:column}.insights-grid{grid-template-columns:1fr}}
.auth-check{text-align:center;display:grid;justify-items:center}.auth-check h1{margin-top:18px}.auth-spinner{width:42px;height:42px;border:4px solid var(--soft);border-top-color:var(--dark);border-radius:50%;animation:auth-spin .8s linear infinite}@keyframes auth-spin{to{transform:rotate(360deg)}}


