export default function LessonProgressButton({slug,xp,nextSlug,theoryOnly=false}:{slug:string;xp:number;nextSlug?:string|null;theoryOnly?:boolean}){
  const [done,setDone]=useState(false);
  const [confirmed,setConfirmed]=useState(false);
  const [note,setNote]=useState("");
  const [saving,setSaving]=useState(false);
  const [notice,setNotice]=useState("");

  useEffect(()=>{
    let active=true;
    async function load(){
      try{
        const saved=JSON.parse(localStorage.getItem("kivronix_lesson_done")||"[]");
        if(Array.isArray(saved)&&saved.includes(slug)&&active)setDone(true);
      }catch{}
      const supabase=getSupabaseBrowserClient();
      const {data:{user}}=await supabase.auth.getUser();
      if(!user)return;
      const {data}=await supabase.from("lesson_progress")
        .select("status,lessons!inner(slug)")
        .eq("user_id",user.id)
        .eq("status","completed")
        .eq("lessons.slug",slug)
        .maybeSingle();
      if(active)setDone(Boolean(data));
    }
    void load();
    return()=>{active=false};
  },[slug]);

  async function complete(){
    if(saving||done||!confirmed)return;
    setSaving(true);setNotice("");
    try{
      const supabase=getSupabaseBrowserClient();
      const {data:{session}}=await supabase.auth.getSession();
      if(session?.access_token){
        const response=await fetch("/api/lessons/progress",{
          method:"POST",
          headers:{"Content-Type":"application/json",Authorization:"Bearer "+session.access_token},
          body:JSON.stringify({slug,completed:true,taskConfirmed:true,submissionNote:note})
        });
        const data=await response.json();
        if(!response.ok)throw new Error(data?.error||"Ошибка сохранения прогресса.");
        void fetch("/api/referral/qualify",{method:"POST",headers:{Authorization:"Bearer "+session.access_token}}).catch(()=>{});
      }

      const saved=JSON.parse(localStorage.getItem("kivronix_lesson_done")||"[]");
      const values=Array.isArray(saved)?saved.filter((item):item is string=>typeof item==="string"):[];
      localStorage.setItem("kivronix_lesson_done",JSON.stringify(Array.from(new Set([...values,slug]))));
      setDone(true);
      setNotice(theoryOnly?"Урок завершён. Следующий урок открыт.":"Задание принято. Следующий урок открыт.");
      window.dispatchEvent(new CustomEvent("kivronix:lesson-completed",{detail:{slug}}));
    }catch(error){
      setNotice(error instanceof Error?error.message:"Ошибка сохранения задания.");
    }finally{setSaving(false)}
  }

  return <div className="lesson-progress-action">
    {!done?<>
      <label className="task-confirm-row"><input type="checkbox" checked={confirmed} onChange={event=>setConfirmed(event.target.checked)}/><span>{theoryOnly?"Я прочитал урок и могу объяснить его главную мысль своими словами.":"Я выполнил задание и проверил результат по чек-листу."}</span></label>
      {!theoryOnly?<textarea value={note} onChange={event=>setNote(event.target.value)} maxLength={1000} rows={2} placeholder="Можно написать, что получилось или где было сложно"/>:null}
      <button className="btn btn-lime" type="button" onClick={complete} disabled={saving||!confirmed}>{saving?"Сохраняю…":theoryOnly?"Всё понятно · +"+xp+" опыта":"Сдать задание · +"+xp+" опыта"}</button>
    </>:<div className="lesson-complete-box"><b>{theoryOnly?"Теория пройдена":"Задание выполнено"}</b><span>Прогресс сохранён, следующий урок открыт.</span>{nextSlug?<Link className="btn btn-dark" href={"/academy/"+nextSlug}>Перейти к следующему уроку →</Link>:<Link className="btn btn-dark" href="/platform#academy">Вернуться в Академию</Link>}</div>}
    {notice?<small>{notice}</small>:null}
  </div>;
}

"use client";

import Link from "next/link";
import {usePathname,useRouter} from "next/navigation";
import {useEffect,useState} from "react";
import {getSupabaseBrowserClient} from "@/lib/supabase-browser";
import {curriculum,learningStartIndex} from "@/lib/curriculum";

export default function LessonRouteGate({requiredSlugs,previousSlug,children}:{requiredSlugs:string[];previousSlug?:string|null;children:React.ReactNode}){
  const router=useRouter();
  const pathname=usePathname();
  const [checking,setChecking]=useState(true);
  const [unlocked,setUnlocked]=useState(false);

  useEffect(()=>{
    let active=true;
    async function check(){
      let completed:string[]=[];
      try{
        const saved=JSON.parse(localStorage.getItem("kivronix_lesson_done")||"[]");
        if(Array.isArray(saved))completed=saved.filter((item):item is string=>typeof item==="string");
      }catch{}

      const supabase=getSupabaseBrowserClient();
      const {data:{user}}=await supabase.auth.getUser();
      if(!user){
        router.replace("/login?from="+encodeURIComponent(pathname));
        return;
      }
      if(user){
        const {data:profile}=await supabase.from("profiles").select("onboarding").eq("id",user.id).maybeSingle();
        const {data}=await supabase.from("lesson_progress")
          .select("status,lessons!inner(slug)")
          .eq("user_id",user.id)
          .eq("status","completed");
        const fromAccount=(data||[]).map((row:any)=>row.lessons?.slug).filter((slug:any)=>typeof slug==="string");
        completed=fromAccount;
        const startIndex=learningStartIndex(profile?.onboarding?.level);
        const currentIndex=curriculum.findIndex(item=>item.slug===pathname.split("/").pop());
        const requiredForLevel=currentIndex>=0?curriculum.slice(startIndex,currentIndex).map(item=>item.slug):requiredSlugs;
        if(active){setUnlocked(currentIndex<=startIndex||requiredForLevel.every(slug=>completed.includes(slug)));setChecking(false)}
        try{localStorage.setItem("kivronix_lesson_done",JSON.stringify(completed))}catch{}
        return;
      }

      if(active){setUnlocked(requiredSlugs.every(slug=>completed.includes(slug)));setChecking(false)}
    }
    void check();
    return()=>{active=false};
  },[pathname,requiredSlugs,router]);

  if(checking)return <div className="lesson-gate-card"><b>Проверяем вход и прогресс…</b></div>;
  if(!unlocked)return <div className="lesson-gate-card locked"><div className="eyebrow">УРОК ПОКА ЗАКРЫТ</div><h2>Сначала заверши предыдущий урок</h2><p>Уроки открываются по порядку: основа всегда идёт раньше сложных инструментов.</p><div>{previousSlug?<Link className="btn btn-dark" href={"/academy/"+previousSlug}>Вернуться к предыдущему уроку</Link>:null}<Link className="btn btn-ghost" href="/platform#academy">Открыть маршрут</Link></div></div>;
  return <>{children}</>;
}

