import {FormEvent,useEffect,useState} from "react";
import {getSupabaseBrowserClient} from "@/lib/supabase-browser";

type Item={id:string;title:string;video_url:string;display_url?:string;tags:string[];ai_score:number|null};

const demo:Item[]=[
  {id:"d1",title:"VOLT — реклама зала",video_url:"",tags:["реклама","спорт"],ai_score:91},
  {id:"d2",title:"Разговор с финансовым экспертом",video_url:"",tags:["эксперт","субтитры"],ai_score:86},
  {id:"d3",title:"North Coffee",video_url:"",tags:["кофе","победитель"],ai_score:90},
];

export default function PortfolioPanel(){
  const [items,setItems]=useState<Item[]>([]);
  const [demoMode,setDemoMode]=useState(false);
  const [form,setForm]=useState({title:"",url:"",tags:""});
  const [message,setMessage]=useState("");

  useEffect(()=>{void load()},[]);

  async function load(){
    const supabase=getSupabaseBrowserClient();
    if(!supabase){setItems(demo);setDemoMode(true);return;}
    const {data:{user}}=await supabase.auth.getUser();
    if(!user){setItems(demo);setDemoMode(true);return;}

    const {data,error}=await supabase.from("portfolio_items").select("id,title,video_url,tags,ai_score").eq("editor_id",user.id).order("created_at",{ascending:false});
    if(error){setMessage(error.message);return;}
    const rows=(data||[]) as Item[];
    const mapped=await Promise.all(rows.map(async item=>{
      if(/^https?:\/\//.test(item.video_url))return {...item,display_url:item.video_url};
      const {data:signed}=await supabase.storage.from("challenge-submissions").createSignedUrl(item.video_url,60*60);
      return {...item,display_url:signed?.signedUrl||""};
    }));
    setItems(mapped);
  }

  async function add(e:FormEvent){
    e.preventDefault();
    const supabase=getSupabaseBrowserClient();
    if(!supabase){setMessage("В примере работа хранится только до обновления страницы. В аккаунте она попадёт в публичный профиль.");return;}
    const {data:{user}}=await supabase.auth.getUser();
    if(!user){setMessage("Войди в аккаунт, чтобы добавить работу.");return;}
    const tags=form.tags.split(",").map(v=>v.trim()).filter(Boolean);
    const {error}=await supabase.from("portfolio_items").insert({editor_id:user.id,title:form.title,video_url:form.url,tags});
    if(error){setMessage(error.message);return;}
    setForm({title:"",url:"",tags:""});setMessage("Работа добавлена.");
    await load();
  }

  return <div className="portfolio-panel">
    <section className="card">
      <div className="eyebrow">НОВАЯ РАБОТА</div><h3>Добавить работу в портфолио</h3>
      <form className="business-form" onSubmit={add}>
        <input required placeholder="Название работы" value={form.title} onChange={e=>setForm({...form,title:e.target.value})}/>
        <input required type="url" placeholder="Ссылка на видео (YouTube/Vimeo/Drive/прямая ссылка)" value={form.url} onChange={e=>setForm({...form,url:e.target.value})}/>
        <input placeholder="Темы через запятую: реклама, спорт, эксперт" value={form.tags} onChange={e=>setForm({...form,tags:e.target.value})}/>
        <button className="btn btn-dark">Добавить</button>
      </form>
      {message&&<div className="auth-msg">{message}</div>}
      {demoMode&&<p className="muted">Сейчас показан пример. После входа здесь будут ваши работы.</p>}
    </section>

    <section className="portfolio-work-grid portfolio-live-grid">
      {items.length?items.map(item=><article className="portfolio-work" key={item.id}>
        <div className="work-preview">{item.display_url&&isDirectVideo(item.display_url)?<video controls preload="metadata" src={item.display_url}/>:<span>РАБОТА KIVRONIX</span>}</div>
        <h2>{item.title}</h2>
        <div className="work-meta"><span>{item.tags.join(" · ")}</span>{item.ai_score!=null&&<b>Оценка {item.ai_score}</b>}</div>
        {item.display_url&&!isDirectVideo(item.display_url)&&<a className="work-link" href={item.display_url} target="_blank" rel="noreferrer">Открыть работу ↗</a>}
      </article>):<div className="card"><p>Добавь первую работу или выиграй конкурс — она появится здесь.</p></div>}
    </section>
  </div>
}

function isDirectVideo(url:string){return /\.(mp4|webm|mov)(\?|$)/i.test(url)||url.includes("supabase")}

"use client";

import Link from "next/link";
import {FormEvent,useEffect,useRef,useState} from "react";
import ProfileAvatar from "@/components/profile-avatar";
import {getSupabaseBrowserClient} from "@/lib/supabase-browser";
import {findPrivateChatBlockReason,privateChatBlockMessage} from "@/lib/private-chat-moderation";

type Conversation={
  id:string;
  side:"editor"|"company";
  source_kind:"campaign"|"challenge"|"job"|"kivronix_contest";
  source_id:string;
  otherName:string;
  otherUsername?:string|null;
  otherAvatar?:string|null;
  company_name:string;
  title:string;
  status:"active"|"closed";
  last_message_at:string;
};

type Message={id:string;conversation_id:string;sender_id:string;body:string;created_at:string};

export default function PrivateChats(){
  const [signedIn,setSignedIn]=useState<boolean|null>(null);
  const [viewerId,setViewerId]=useState("");
  const [conversations,setConversations]=useState<Conversation[]>([]);
  const [selectedId,setSelectedId]=useState("");
  const [messages,setMessages]=useState<Message[]>([]);
  const [draft,setDraft]=useState("");
  const [notice,setNotice]=useState("");
  const [sending,setSending]=useState(false);
  const endRef=useRef<HTMLDivElement|null>(null);

  async function token(){
    const supabase=getSupabaseBrowserClient();
    const {data:{session}}=await supabase.auth.getSession();
    return session?.access_token||"";
  }

  async function loadConversations(){
    const access=await token();
    if(!access){setSignedIn(false);return;}
    setSignedIn(true);
    const response=await fetch("/api/private-chats",{headers:{Authorization:"Bearer "+access},cache:"no-store"});
    const data=await response.json().catch(()=>({}));
    if(!response.ok){setNotice(data?.error||"Ошибка загрузки чатов.");return;}
    const next=(data.conversations||[]) as Conversation[];
    let preferred="";
    let preferredSource="";
    try{
      preferred=sessionStorage.getItem("kivronix_open_conversation")||"";
      preferredSource=sessionStorage.getItem("kivronix_open_chat_source")||"";
      sessionStorage.removeItem("kivronix_open_conversation");
      sessionStorage.removeItem("kivronix_open_chat_source");
    }catch{}
    const sourceMatch=preferredSource?next.find(item=>item.source_kind+":"+item.source_id===preferredSource)?.id||"":"";
    setViewerId(data.viewerId||"");
    setConversations(next);
    setSelectedId(current=>{
      if(preferred&&next.some(item=>item.id===preferred))return preferred;
      if(sourceMatch)return sourceMatch;
      if(current&&next.some(item=>item.id===current))return current;
      return next[0]?.id||"";
    });
  }

  async function loadMessages(id:string,silent=false){
    if(!id)return;
    const access=await token();
    if(!access){setSignedIn(false);return;}
    const response=await fetch("/api/private-chats?conversationId="+encodeURIComponent(id),{headers:{Authorization:"Bearer "+access},cache:"no-store"});
    const data=await response.json().catch(()=>({}));
    if(!response.ok){if(!silent)setNotice(data?.error||"Ошибка загрузки сообщений.");return;}
    setViewerId(data.viewerId||"");
    setMessages(data.messages||[]);
  }

  useEffect(()=>{void loadConversations()},[]);

  useEffect(()=>{
    if(!selectedId){setMessages([]);return;}
    void loadMessages(selectedId);
    const supabase=getSupabaseBrowserClient();
    const channel=supabase.channel("private-chat-"+selectedId)
      .on("postgres_changes",{event:"INSERT",schema:"public",table:"private_messages",filter:"conversation_id=eq."+selectedId},()=>void loadMessages(selectedId,true))
      .subscribe();
    const timer=window.setInterval(()=>void loadMessages(selectedId,true),5000);
    return()=>{window.clearInterval(timer);void supabase.removeChannel(channel)};
  },[selectedId]);

  useEffect(()=>{endRef.current?.scrollIntoView({behavior:"smooth",block:"nearest"})},[messages]);

  async function send(event:FormEvent){
    event.preventDefault();
    const message=draft.trim();
    if(!message||!selectedId||sending)return;
    if(findPrivateChatBlockReason(message)){setNotice(privateChatBlockMessage());return;}
    setSending(true);setNotice("");
    const access=await token();
    if(!access){setSignedIn(false);setSending(false);return;}
    const response=await fetch("/api/private-chats",{
      method:"POST",
      headers:{"Content-Type":"application/json",Authorization:"Bearer "+access},
      body:JSON.stringify({action:"send",conversationId:selectedId,message})
    });
    const data=await response.json().catch(()=>({}));
    if(response.ok){setDraft("");await loadMessages(selectedId,true);await loadConversations()}
    else setNotice(data?.error||"Ошибка отправки сообщения.");
    setSending(false);
  }

  if(signedIn===null)return <div className="card"><p className="muted">Открываем закрытые чаты…</p></div>;
  if(signedIn===false)return <div className="card private-chat-empty"><div className="private-chat-lock">🔒</div><h3>Войдите в аккаунт</h3><p>Закрытые чаты доступны участникам работы и конкурса.</p><Link className="btn btn-dark" href="/login?from=/platform%23messages">Войти</Link></div>;

  const current=conversations.find(item=>item.id===selectedId)||null;

  return <div className="private-chat-shell">
    <aside className="private-chat-list">
      <div className="private-chat-list-head"><b>Закрытые чаты</b><span>{conversations.length}</span></div>
      {conversations.length===0?<div className="private-chat-zero"><span>💬</span><b>Чаты появятся здесь</b><p>Компания принимает монтажёра или выбирает победителя конкурса. После этого система открывает общий чат.</p></div>:conversations.map(item=><button type="button" className={item.id===selectedId?"active":""} key={item.id} onClick={()=>{setSelectedId(item.id);setNotice("")}}>
        <ProfileAvatar src={item.otherAvatar} name={item.otherName} size="sm"/>
        <span><b>{item.otherName}</b><small>{sourceLabel(item.source_kind)}</small></span>
        <time>{shortDate(item.last_message_at)}</time>
      </button>)}
    </aside>

    <section className="private-chat-thread">
      {current?<>
        <header><div><div className="private-chat-title"><span className="private-chat-shield">◆</span><div><h3>{current.otherName}</h3><p>{current.title}</p></div></div></div><span className="private-chat-badge">Закрытый чат</span></header>
        <div className="private-chat-safety"><b>Сообщения видят только компания и монтажёр.</b><span>Телефоны, электронная почта, ссылки, адреса страниц и названия мессенджеров остаются за пределами чата. Общайтесь внутри KIVRONIX.</span></div>
        <div className="private-chat-messages" aria-live="polite">
          {messages.length===0?<div className="private-chat-start"><span>👋</span><b>Можно начинать</b><p>Обсудите задачу, срок, готовый результат и правки простыми словами.</p></div>:messages.map(item=><article className={item.sender_id===viewerId?"mine":"theirs"} key={item.id}><p>{item.body}</p><time>{messageTime(item.created_at)}</time></article>)}
          <div ref={endRef}/>
        </div>
        <form className="private-chat-form" onSubmit={send}>
          <textarea value={draft} onChange={event=>setDraft(event.target.value)} maxLength={1500} rows={3} placeholder="Напишите сообщение о работе…" disabled={current.status!=="active"}/>
          <div><small>{draft.length} / 1500</small><button className="btn btn-dark" disabled={sending||!draft.trim()||current.status!=="active"}>{sending?"Отправляем…":"Отправить"}</button></div>
        </form>
        {notice?<div className="auth-msg">{notice}</div>:null}
      </>:<div className="private-chat-zero large"><span>🔒</span><b>Выберите чат</b><p>Здесь будет ваш разговор о работе.</p></div>}
    </section>
  </div>;
}

function sourceLabel(value:Conversation["source_kind"]){
  if(value==="campaign")return "Работа с компанией";
  if(value==="challenge")return "Конкурс компании";
  if(value==="job")return "Вакансия";
  return "Конкурс KIVRONIX";
}

function shortDate(value:string){
  const date=new Date(value);
  const today=new Date();
  return date.toDateString()===today.toDateString()?date.toLocaleTimeString("ru-RU",{hour:"2-digit",minute:"2-digit"}):date.toLocaleDateString("ru-RU",{day:"2-digit",month:"2-digit"});
}

function messageTime(value:string){
  return new Date(value).toLocaleString("ru-RU",{day:"numeric",month:"short",hour:"2-digit",minute:"2-digit"});
}

export default function ProfileAvatar({src,name,size="md"}:{src?:string|null;name?:string|null;size?:"sm"|"md"|"lg"}){
  const initial=(name||"E").trim().charAt(0).toUpperCase()||"E";
  return <span className={"profile-avatar "+size} aria-label={name||"Профиль"}>
    {src?<img src={src} alt="" loading="lazy"/>:<b aria-hidden="true">{initial}</b>}
  </span>;
}

"use client";

import {FormEvent,useEffect,useRef,useState} from "react";
import {getSupabaseBrowserClient} from "@/lib/supabase-browser";
import ProfileAvatar from "@/components/profile-avatar";

type ProfileForm={displayName:string;username:string;schoolName:string;avatarUrl:string;showSchoolPublicly:boolean};

export default function ProfileEditor({onSaved}:{onSaved?:(profile:ProfileForm)=>void}){
  const [form,setForm]=useState<ProfileForm>({displayName:"",username:"",schoolName:"",avatarUrl:"",showSchoolPublicly:false});
  const [loading,setLoading]=useState(true);
  const [saving,setSaving]=useState(false);
  const [message,setMessage]=useState("");
  const fileRef=useRef<HTMLInputElement>(null);

  useEffect(()=>{
    let active=true;
    async function load(){
      const supabase=getSupabaseBrowserClient();
      const {data:{user}}=await supabase.auth.getUser();
      if(!user){if(active){setMessage("Войди в аккаунт, чтобы изменить профиль.");setLoading(false)};return;}
      const {data}=await supabase.from("profiles")
        .select("display_name,username,school_name,avatar_url,show_school_publicly")
        .eq("id",user.id).maybeSingle();
      if(active){
        setForm({displayName:data?.display_name||"",username:data?.username||"",schoolName:data?.school_name||"",avatarUrl:data?.avatar_url||"",showSchoolPublicly:Boolean(data?.show_school_publicly)});
        setLoading(false);
      }
    }
    void load();
    return()=>{active=false};
  },[]);

  async function save(event:FormEvent){
    event.preventDefault();
    if(saving)return;
    const displayName=form.displayName.trim().replace(/\s+/g," ");
    const username=form.username.trim().replace(/^@/,"").toLowerCase();
    const schoolName=form.schoolName.trim().replace(/\s+/g," ");
    if(displayName.length<2){setMessage("Имя должно содержать 2 символа или больше.");return;}
    if(!/^[a-z0-9][a-z0-9._-]{2,29}$/.test(username)){setMessage("Адрес страницы: 3–30 символов. Подойдут латинские буквы, цифры, точка, дефис и подчёркивание.");return;}
    if(schoolName&&schoolName.length<2){setMessage("Проверь название школы.");return;}

    setSaving(true);setMessage("");
    const supabase=getSupabaseBrowserClient();
    const {data:{user}}=await supabase.auth.getUser();
    if(!user){setSaving(false);setMessage("Сессия закончилась. Войди снова.");return;}

    let avatarUrl=form.avatarUrl;
    const file=fileRef.current?.files?.[0];
    if(file){
      if(!["image/jpeg","image/png","image/webp"].includes(file.type)){setSaving(false);setMessage("Аватар должен быть JPG, PNG или WebP.");return;}
      if(file.size>5*1024*1024){setSaving(false);setMessage("Аватар должен быть меньше 5 МБ.");return;}
      const ext=file.type==="image/png"?"png":file.type==="image/webp"?"webp":"jpg";
      const path=user.id+"/avatar."+ext;
      const {error:uploadError}=await supabase.storage.from("avatars").upload(path,file,{upsert:true,contentType:file.type,cacheControl:"3600"});
      if(uploadError){setSaving(false);setMessage("Ошибка загрузки изображения: "+uploadError.message);return;}
      avatarUrl=supabase.storage.from("avatars").getPublicUrl(path).data.publicUrl+"?v="+Date.now();
    }

    const {error}=await supabase.from("profiles").update({
      display_name:displayName,
      username,
      school_name:schoolName||null,
      avatar_url:avatarUrl||null,
      show_school_publicly:Boolean(schoolName&&form.showSchoolPublicly)
    }).eq("id",user.id);
    setSaving(false);
    if(error){
      setMessage(error.code==="23505"?"Этот адрес страницы уже занят. Попробуй другой.":"Ошибка сохранения профиля: "+error.message);
      return;
    }
    const next={displayName,username,schoolName,avatarUrl,showSchoolPublicly:Boolean(schoolName&&form.showSchoolPublicly)};
    setForm(next);setMessage(next.showSchoolPublicly?"Профиль сохранён. Школа участвует в командном рейтинге.":"Профиль сохранён. Название школы видно только тебе.");onSaved?.(next);
    if(fileRef.current)fileRef.current.value="";
  }

  if(loading)return <section className="card"><p className="muted">Загружаю профиль…</p></section>;

  return <section className="card profile-editor-card">
    <div className="profile-editor-head"><ProfileAvatar src={form.avatarUrl} name={form.displayName} size="lg"/><div><div className="eyebrow">ТВОЙ ПРОФИЛЬ</div><h3>Фото, имя и команда</h3></div></div>
    <form className="business-form" onSubmit={save}>
      <label className="field-label">Фото профиля</label>
      <input ref={fileRef} type="file" accept="image/jpeg,image/png,image/webp"/>
      <label className="field-label">Имя</label>
      <input required maxLength={120} value={form.displayName} onChange={event=>setForm({...form,displayName:event.target.value})}/>
      <label className="field-label">Короткий адрес твоей страницы</label>
      <input required maxLength={30} value={form.username} onChange={event=>setForm({...form,username:event.target.value})} placeholder="editor-name"/>
      <label className="field-label">Школа, колледж или вуз</label>
      <input maxLength={160} value={form.schoolName} onChange={event=>setForm({...form,schoolName:event.target.value})} placeholder="Необязательно"/>
      <label className="consent-row"><input type="checkbox" checked={form.showSchoolPublicly} disabled={!form.schoolName.trim()} onChange={event=>setForm({...form,showSchoolPublicly:event.target.checked})}/><span>Показывать название учебного заведения в профиле и учитывать его в рейтинге школ.</span></label>
      <small className="field-hint">По умолчанию школа скрыта. Класс, адрес, смену и телефон оставь за пределами профиля.</small>
      <button className="btn btn-dark" disabled={saving}>{saving?"Сохраняю…":"Сохранить профиль"}</button>
    </form>
    {message?<div className="auth-msg">{message}</div>:null}
  </section>;
}

