{
  "name": "kivronix",
  "version": "0.2.0",
  "private": true,
  "scripts": {
    "dev": "next dev",
    "build": "next build",
    "start": "next start",
    "email:test": "node --env-file-if-exists=.env.local scripts/resend-hello.mjs",
    "typecheck": "tsc --noEmit",
    "check": "npm run typecheck && npm run build"
  },
  "dependencies": {
    "@supabase/supabase-js": "^2.57.4",
    "next": "16.3.3",
    "react": "^19.2.0",
    "react-dom": "^19.2.0",
    "resend": "6.28.0"
  },
  "devDependencies": {
    "@types/node": "^22.0.0",
    "@types/react": "^19.0.0",
    "@types/react-dom": "^19.0.0",
    "typescript": "^5.9.2"
  }
}

import {Resend} from "resend";

const apiKey=process.env.RESEND_API_KEY;
const to=process.argv[2];

if(!apiKey||apiKey==="re_xxxxxxxxx"){
  throw new Error("Replace re_xxxxxxxxx with your real Resend API key in RESEND_API_KEY.");
}

if(!to){
  throw new Error("Pass the recipient: npm run email:test -- you@example.com");
}

const resend=new Resend(apiKey);
const {data,error}=await resend.emails.send({
  from:"onboarding@resend.dev",
  to,
  subject:"Hello World",
  html:"<p>Congrats on sending your <strong>first email</strong>!</p>",
});

if(error)throw new Error(error.message);

console.log("Email sent:",data?.id);

{
  "compilerOptions": {
    "target": "ES2022",
    "lib": [
      "dom",
      "dom.iterable",
      "esnext"
    ],
    "allowJs": false,
    "skipLibCheck": true,
    "strict": true,
    "noEmit": true,
    "esModuleInterop": true,
    "module": "esnext",
    "moduleResolution": "bundler",
    "resolveJsonModule": true,
    "isolatedModules": true,
    "jsx": "react-jsx",
    "incremental": true,
    "plugins": [
      {
        "name": "next"
      }
    ],
    "paths": {
      "@/*": [
        "./*"
      ]
    }
  },
  "include": [
    "next-env.d.ts",
    "**/*.ts",
    "**/*.tsx",
    ".next/types/**/*.ts",
    ".next/dev/types/**/*.ts"
  ],
  "exclude": [
    "node_modules"
  ]
}

{
  "$schema": "https://openapi.vercel.sh/vercel.json",
  "alias": [
    "kivronix.ru",
    "www.kivronix.ru",
    "kivronix.com",
    "www.kivronix.com"
  ]
}
